@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
    <select class="form-select w-auto" @bind="statusFilter">
        <option value="">All Statuses</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <a href="dispatcher/create" class="btn btn-primary text-nowrap">+ New Shipment</a>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="(e) => UpdateStatus(s, e)">
                                    <option value="">Change status...</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetShipmentsAsync();
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var result = await ShipmentService.UpdateStatusAsync(shipment.Id, new UpdateShipmentStatusRequest
            {
                NewStatus = newStatus,
                EstimatedDelivery = shipment.EstimatedDelivery
            });

            if (result is not null)
            {
                var index = shipments!.FindIndex(s => s.Id == shipment.Id);
                if (index >= 0) shipments[index] = result;
            }
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher/create"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject ShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Create Shipment</PageTitle>

<h1>Create New Shipment</h1>

<div class="row">
    <div class="col-md-8 col-lg-6">
        <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="CreateShipment">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label class="form-label">Origin</label>
                <InputText class="form-control" @bind-Value="model.Origin" placeholder="e.g., New York, NY" />
            </div>

            <div class="mb-3">
                <label class="form-label">Destination</label>
                <InputText class="form-control" @bind-Value="model.Destination" placeholder="e.g., Los Angeles, CA" />
            </div>

            <div class="mb-3">
                <label class="form-label">Customer Email</label>
                <InputText class="form-control" type="email" @bind-Value="model.CustomerEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Description</label>
                <InputText class="form-control" @bind-Value="model.Description" placeholder="Package contents" />
            </div>

            <div class="mb-3">
                <label class="form-label">Estimated Delivery</label>
                <InputDate class="form-control" @bind-Value="model.EstimatedDelivery" />
            </div>

            <button type="submit" class="btn btn-primary" disabled="@isSubmitting">
                @(isSubmitting ? "Creating..." : "Create Shipment")
            </button>
            <a href="dispatcher" class="btn btn-outline-secondary ms-2">Cancel</a>

            @if (!string.IsNullOrEmpty(errorMessage))
            {
                <div class="alert alert-danger mt-3">@errorMessage</div>
            }
        </EditForm>
    </div>
</div>

@code {
    private ShipmentFormModel model = new();
    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        errorMessage = null;

        var dto = new ShipmentDto
        {
            Origin = model.Origin,
            Destination = model.Destination,
            CustomerEmail = model.CustomerEmail,
            Description = model.Description,
            EstimatedDelivery = model.EstimatedDelivery
        };

        var result = await ShipmentService.CreateShipmentAsync(dto);
        if (result is not null)
        {
            Navigation.NavigateTo("/dispatcher");
        }
        else
        {
            errorMessage = "Failed to create shipment. Please try again.";
            isSubmitting = false;
        }
    }

    private class ShipmentFormModel
    {
        public string Origin { get; set; } = string.Empty;
        public string Destination { get; set; } = string.Empty;
        public string CustomerEmail { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        public DateTime? EstimatedDelivery { get; set; } = DateTime.Today.AddDays(5);
    }
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject ShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-8 col-lg-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260601-10001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && trackedShipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please verify and try again.
    </div>
}

@if (trackedShipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h5 class="mb-0">Shipment <code>@trackedShipment.TrackingNumber</code></h5>
            <span class="badge @GetStatusBadgeClass(trackedShipment.Status) fs-6">@trackedShipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>From:</strong> @trackedShipment.Origin</p>
                    <p><strong>To:</strong> @trackedShipment.Destination</p>
                    <p><strong>Description:</strong> @trackedShipment.Description</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Shipped:</strong> @trackedShipment.CreatedAt.ToString("MMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong>
                        @(trackedShipment.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "Not yet determined")
                    </p>
                </div>
            </div>

            <!-- Progress indicator -->
            <div class="mt-4">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(trackedShipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(trackedShipment.Status))%"
                         aria-valuenow="@GetProgressPercent(trackedShipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @trackedShipment.Status
                    </div>
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h3>Your Shipments</h3>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <p>You have no shipments yet.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>From</th>
                    <th>To</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in myShipments)
                {
                    <tr class="cursor-pointer" @onclick="() => SelectShipment(s)">
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? trackedShipment;
    private List<ShipmentDto>? myShipments;
    private bool isSearching;
    private bool searched;

    protected override async Task OnInitializedAsync()
    {
        myShipments = await ShipmentService.GetShipmentsAsync();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searched = true;
        searchedNumber = trackingNumber.Trim();
        trackedShipment = await ShipmentService.TrackShipmentAsync(searchedNumber);
        isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await SearchShipment();
    }

    private void SelectShipment(ShipmentDto shipment)
    {
        trackedShipment = shipment;
        trackingNumber = shipment.TrackingNumber;
        searched = true;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };
}

